import { Component, ElementRef, ViewChild } from '@angular/core';

type Item = { id: string; label: string };
type Snapshot = { top: Item[]; bottom: Item[] };

const rowsMatching = (items: Item[], search: string): Item[] => {
  const term = search.trim().toLowerCase();
  return items.filter((item) => item.label.toLowerCase().includes(term));
};

const withSelection = (selected: Set<string>, ids: string[], checked: boolean): Set<string> => {
  const next = new Set(selected);
  for (const id of ids) {
    if (checked) next.add(id);
    else next.delete(id);
  }
  return next;
};

@Component({
  selector: 'app-root',
  standalone: true,
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  @ViewChild('topTitle') topTitle!: ElementRef<HTMLElement>;
  @ViewChild('bottomTitle') bottomTitle!: ElementRef<HTMLElement>;

  topItems: Item[] = [
    { id: 'a', label: 'Alpha' },
    { id: 'b', label: 'Beta' },
    { id: 'c', label: 'Gamma' },
    { id: 'd', label: 'Delta' },
    { id: 'e', label: 'Epsilon' }
  ];

  bottomItems: Item[] = [
    { id: 'x', label: 'Xenon' },
    { id: 'y', label: 'Yttrium' },
    { id: 'z', label: 'Zinc' }
  ];

  topSelected = new Set<string>();
  bottomSelected = new Set<string>();
  topSearch = '';
  bottomSearch = '';
  status = '';

  // Snapshots, because moving items back would not restore their order.
  private history: Snapshot[] = [];

  // Only the rows on screen count for select all, the count and the move buttons.
  get visibleTop(): Item[] {
    return rowsMatching(this.topItems, this.topSearch);
  }

  get visibleBottom(): Item[] {
    return rowsMatching(this.bottomItems, this.bottomSearch);
  }

  get selectedTop(): Item[] {
    return this.visibleTop.filter((item) => this.topSelected.has(item.id));
  }

  get selectedBottom(): Item[] {
    return this.visibleBottom.filter((item) => this.bottomSelected.has(item.id));
  }

  get canMoveDown(): boolean {
    return this.selectedTop.length > 0;
  }

  get canMoveUp(): boolean {
    return this.selectedBottom.length > 0;
  }

  get canUndo(): boolean {
    return this.history.length > 0;
  }

  isTopSelected(id: string): boolean {
    return this.topSelected.has(id);
  }

  isBottomSelected(id: string): boolean {
    return this.bottomSelected.has(id);
  }

  toggleTop(id: string, checked: boolean): void {
    this.topSelected = withSelection(this.topSelected, [id], checked);
  }

  toggleBottom(id: string, checked: boolean): void {
    this.bottomSelected = withSelection(this.bottomSelected, [id], checked);
  }

  toggleAllTop(): void {
    const rows = this.visibleTop;
    const select = this.selectedTop.length < rows.length;
    this.topSelected = withSelection(this.topSelected, rows.map((item) => item.id), select);
  }

  toggleAllBottom(): void {
    const rows = this.visibleBottom;
    const select = this.selectedBottom.length < rows.length;
    this.bottomSelected = withSelection(this.bottomSelected, rows.map((item) => item.id), select);
  }

  moveDown(): void {
    const moved = this.selectedTop;
    if (moved.length === 0) return;
    const ids = moved.map((item) => item.id);

    this.remember();
    this.topItems = this.topItems.filter((item) => !ids.includes(item.id));
    this.bottomItems = [...this.bottomItems, ...moved];
    this.topSelected = withSelection(this.topSelected, ids, false);
    this.announce(moved.length, 'Bottom');
    // The pressed button may turn off, so focus goes to where the items went.
    this.bottomTitle.nativeElement.focus();
  }

  moveUp(): void {
    const moved = this.selectedBottom;
    if (moved.length === 0) return;
    const ids = moved.map((item) => item.id);

    this.remember();
    this.bottomItems = this.bottomItems.filter((item) => !ids.includes(item.id));
    this.topItems = [...this.topItems, ...moved];
    this.bottomSelected = withSelection(this.bottomSelected, ids, false);
    this.announce(moved.length, 'Top');
    this.topTitle.nativeElement.focus();
  }

  undo(): void {
    const snapshot = this.history.pop();
    if (!snapshot) return;
    this.topItems = snapshot.top;
    this.bottomItems = snapshot.bottom;
    this.topSelected = new Set<string>();
    this.bottomSelected = new Set<string>();
    this.status = 'Move undone';
    // The last undo turns this button off.
    if (!this.canUndo) this.topTitle.nativeElement.focus();
  }

  private remember(): void {
    this.history.push({ top: this.topItems, bottom: this.bottomItems });
  }

  private announce(count: number, title: string): void {
    this.status = `${count} ${count === 1 ? 'item' : 'items'} moved to ${title}`;
  }
}

